import { useEffect, useState } from "react";
import { motion } from "framer-motion";

export default function Testimonials() {
  const [reviews, setReviews] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("http://localhost:5001/admin/reviews")
      .then((res) => res.json())
      .then((data) => {
        const activeReviews = data.filter(
          (r) => r.status === "Active"
        );
        setReviews(activeReviews);
      })
      .catch((err) => console.error("Reviews fetch error:", err))
      .finally(() => setLoading(false));
  }, []);

  return (
    <section className="bg-black pt-28 pb-24 px-6 min-h-screen overflow-hidden">
      <div className="max-w-7xl mx-auto">
        {/* HEADING */}
        <motion.h2
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="text-4xl md:text-5xl font-bold text-center text-white mb-6"
        >
          What Our <span className="text-[#e9b21a]">Members Say</span>
        </motion.h2>

        <p className="text-center text-gray-400 max-w-2xl mx-auto mb-16">
          Real experiences from real people who train with discipline,
          structure, and purpose at BodyZeal Fitworks.
        </p>

        {/* LOADING */}
        {loading && (
          <p className="text-center text-gray-400">
            Loading testimonials...
          </p>
        )}

        {/* EMPTY */}
        {!loading && reviews.length === 0 && (
          <p className="text-center text-gray-400">
            No testimonials available yet.
          </p>
        )}

        {/* TESTIMONIALS GRID */}
        <div className="grid gap-10 sm:grid-cols-1 md:grid-cols-2 lg:grid-cols-3">
          {reviews.map((r, i) => (
            <motion.div
              key={r.id}
              initial={{ opacity: 0, y: 40 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: i * 0.08 }}
              whileHover={{ y: -8 }}
              className="relative rounded-3xl p-8 bg-gradient-to-br from-black via-black to-[#e9b21a]/5
                         border border-[#e9b21a]/30 shadow-[0_0_40px_rgba(233,178,26,0.15)]"
            >
              {/* QUOTE ICON */}
              <div className="absolute -top-6 -left-6 w-14 h-14 rounded-full
                              bg-[#e9b21a] text-black flex items-center justify-center
                              text-4xl font-serif shadow-lg">
                “
              </div>

              {/* MESSAGE */}
              <p className="text-gray-300 leading-relaxed italic">
                {r.message}
              </p>

              {/* STARS */}
              <div className="flex gap-1 mt-6">
                {Array.from({ length: 5 }).map((_, idx) => (
                  <span
                    key={idx}
                    className={
                      idx < r.rating
                        ? "text-[#e9b21a]"
                        : "text-gray-600"
                    }
                  >
                    ★
                  </span>
                ))}
              </div>

              {/* NAME */}
              <div className="mt-4 text-[#e9b21a] font-semibold text-lg">
                {r.name}
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
